import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchFallLocationWarningById,
  createFallLocationWarning,
  updateFallLocationWarning,
  setSelectedWarning,
} from '../../store/slices/fallLocationWarningsSlice';
import { addToast } from '../../store/slices/uiSlice';
import {
  FallLocationWarning,
  FallWarningCurrentStatus,
  FallWarningProposalStatus,
  createEmptyFallLocationWarning,
} from '../../models/FallLocationWarning';
import styles from './FallLocationWarningFormPage.module.css';
import {
  ValidationErrors,
  ValidationRule,
  runValidation,
  scrollToFirstErrorSection,
  clearFieldErrors,
} from '../../utils/formValidation';

// ─── Validation rules ──────────────────────────────────────────────────────
//
// Rules in DOM top-to-bottom section order → scroll always goes to topmost error.
//
import { Button } from '@linm-soft-org/linm-web-common-components';
const FALL_WARNING_RULES: ValidationRule<FallLocationWarning>[] = [
  {
    field:     'surveyDate',
    sectionId: 'fall-section-survey',
    validate:  (f) => !f.surveyDate ? 'Ngày khảo sát là bắt buộc' : null,
  },
  {
    field:     'location',
    sectionId: 'fall-section-survey',
    validate:  (f) => {
      if (!f.location?.trim()) return 'Vị trí là bắt buộc';
      if (f.location.length > 500) return 'Vị trí không được vượt quá 500 ký tự';
      return null;
    },
  },
];

const FallLocationWarningFormPage: React.FC = () => {
  const { id }   = useParams<{ id: string }>();
  const appNavigate = useAppNavigate();
  const dispatch  = useAppDispatch();
  const isNew     = !id || id === 'new';

  const { selectedWarning, saving, loading } = useAppSelector((s) => s.fallLocationWarnings);
  const authUser = useAppSelector((s) => s.auth.user);

  const [form, setForm] = useState<Partial<FallLocationWarning>>(() => {
    if (!id || id === 'new') {
      return {
        ...createEmptyFallLocationWarning(),
        surveyDate: new Date().toISOString().slice(0, 10),
      };
    }
    return {};
  });
  const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});

  // Load existing
  useEffect(() => {
    const t = setTimeout(() => {
      if (!isNew && id) {
        dispatch(fetchFallLocationWarningById(id));
      } else {
        dispatch(setSelectedWarning(null));
      }
    }, 0);
    return () => clearTimeout(t);
  }, [dispatch, id, isNew]);

  // Populate form
  useEffect(() => {
    if (!isNew && selectedWarning) {
      setForm({ ...selectedWarning });
    } else if (isNew) {
      const empty = createEmptyFallLocationWarning();
      setForm({
        ...empty,
        createdById:   authUser?.id ?? '',
        createdByName: authUser?.fullName ?? '',
        surveyDate:    new Date().toISOString().slice(0, 10),
      });
    }
  }, [isNew, selectedWarning, authUser]);

  const patch = (p: Partial<FallLocationWarning>) => {
    setForm((prev) => ({ ...prev, ...p }));
    setValidationErrors((prev) => clearFieldErrors(prev, Object.keys(p)));
  };

  // ── Causes (multi-input) ──────────────────────────────────────────────────
  const causes: string[] = form.causes ?? [''];

  const setCause = (idx: number, val: string) => {
    const next = [...causes];
    next[idx] = val;
    patch({ causes: next });
  };

  const addCause = () => patch({ causes: [...causes, ''] });

  const removeCause = (idx: number) => {
    if (causes.length <= 1) { patch({ causes: [''] }); return; }
    patch({ causes: causes.filter((_, i) => i !== idx) });
  };

  // ── Save ─────────────────────────────────────────────────────────────────
  const handleSave = async () => {
    const errors = runValidation(form, FALL_WARNING_RULES);
    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      scrollToFirstErrorSection(errors, FALL_WARNING_RULES);
      return;
    }
    setValidationErrors({});

    try {
      if (isNew) {
        await dispatch(createFallLocationWarning(form)).unwrap();
        dispatch(addToast({ message: 'Tạo cảnh báo vị trí té ngã thành công', type: 'success' }));
        appNavigate(scykRoutes.fallWarnings.list, { replace: true });
      } else {
        await dispatch(updateFallLocationWarning({ id: id!, data: form })).unwrap();
        dispatch(addToast({ message: 'Cập nhật cảnh báo thành công', type: 'success' }));
      }
    } catch (error: unknown) {
      dispatch(addToast({ message: error instanceof Error ? error.message : 'Đã có lỗi xảy ra', type: 'error' }));
    }
  };

  const handleBack = () => appNavigate(scykRoutes.fallWarnings.list);

  if (loading && !isNew) {
    return (
      <div className={styles.loadingWrap}>
        <i className="fas fa-spinner fa-spin" /> Đang tải...
      </div>
    );
  }

  return (
    <div className={styles.page}>
      {/* Sticky header */}
      <div className={styles.stickyTop}>
        <div className={styles.pageHeader}>
          <div className={styles.titleGroup}>
            <button className={styles.backBtn} onClick={handleBack}>
              <i className="fas fa-arrow-left" />
            </button>
            <div>
              <h1 className={styles.title}>
                {isNew ? 'Thêm cảnh báo vị trí té ngã' : `Cảnh báo: ${form.idCode || '...'}`}
              </h1>
              {!isNew && form.location && <p className={styles.subtitle}>{form.location}</p>}
            </div>
          </div>
          <div className={styles.headerActions}>
            <Button variant="secondary" onClick={handleBack} disabled={saving}>
              Hủy
            </Button>
            <Button variant="primary" onClick={handleSave} disabled={saving}>
              {saving
                ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                : <><i className="fas fa-save" /> Lưu</>
              }
            </Button>
          </div>
        </div>
      {/* Validation error banner */}
        {Object.keys(validationErrors).length > 0 && (
          <div className={styles.errorBanner}>
            <i className="fas fa-exclamation-circle" />
            <div className={styles.errorBannerContent}>
              <strong>Vui lòng điền đầy đủ các trường bắt buộc:</strong>
              <ul className={styles.errorBannerList}>
                {Object.values(validationErrors).map((msg, i) => (
                  <li key={i}>{msg}</li>
                ))}
              </ul>
            </div>
            <button
              className={styles.errorBannerClose}
              onClick={() => setValidationErrors({})}
              aria-label="Đóng thông báo lỗi"
            >
              <i className="fas fa-times" />
            </button>
          </div>
        )}
      </div>

      {/* Form body */}
      <div className={styles.formBody}>

        {/* Section 1: Thông tin khảo sát */}
        <div className={styles.section} id="fall-section-survey">
          <h2 className={styles.sectionTitle}>
            <i className="fas fa-clipboard-list" /> Thông Tin Khảo Sát
          </h2>

          <div className={styles.row}>
            <div className={`${styles.field} ${validationErrors.surveyDate ? styles.fieldHasError : ''}`}>
              <label>Ngày khảo sát *</label>
              <input
                type="date"
                className={validationErrors.surveyDate ? styles.inputError : ''}
                value={form.surveyDate?.slice(0, 10) ?? ''}
                onChange={(e) => patch({ surveyDate: e.target.value })}
              />
              {validationErrors.surveyDate && (
                <span className={styles.fieldError}>{validationErrors.surveyDate}</span>
              )}
            </div>
            <div className={styles.field}>
              <label>Khoa / Phòng</label>
              <input
                type="text"
                placeholder="Tên khoa / phòng..."
                value={form.departmentName ?? ''}
                onChange={(e) => patch({ departmentName: e.target.value })}
              />
            </div>
          </div>

          <div className={`${styles.field} ${validationErrors.location ? styles.fieldHasError : ''}`}>
            <label>Vị trí *</label>
            <input
              type="text"
              className={validationErrors.location ? styles.inputError : ''}
              placeholder="Mô tả vị trí cụ thể (hành lang, cầu thang, phòng...)"
              value={form.location ?? ''}
              onChange={(e) => patch({ location: e.target.value })}
            />
            {validationErrors.location && (
              <span className={styles.fieldError}>{validationErrors.location}</span>
            )}
          </div>

          <div className={styles.field}>
            <label>Nguyên nhân</label>
            <div className={styles.causesWrap}>
              {causes.map((c, idx) => (
                <div key={idx} className={styles.causeRow}>
                  <input
                    type="text"
                    placeholder={`Nguyên nhân ${idx + 1}...`}
                    value={c}
                    onChange={(e) => setCause(idx, e.target.value)}
                  />
                  <button className={styles.removeCause} onClick={() => removeCause(idx)}>
                    <i className="fas fa-times" />
                  </button>
                </div>
              ))}
              <button className={styles.addCause} onClick={addCause}>
                <i className="fas fa-plus" /> Thêm nguyên nhân
              </button>
            </div>
          </div>

          <div className={styles.field}>
            <label>Mô tả chi tiết</label>
            <textarea
              rows={3}
              placeholder="Mô tả chi tiết về nguy cơ té ngã tại vị trí này..."
              value={form.detailedDescription ?? ''}
              onChange={(e) => patch({ detailedDescription: e.target.value })}
            />
          </div>
        </div>

        {/* Section 2: Đề xuất khắc phục */}
        <div className={styles.section} id="fall-section-proposal">
          <h2 className={styles.sectionTitle}>
            <i className="fas fa-tools" /> Đề Xuất Khắc Phục
          </h2>

          <div className={styles.field}>
            <label>Nội dung đề xuất</label>
            <textarea
              rows={3}
              placeholder="Mô tả biện pháp khắc phục đề xuất..."
              value={form.proposedFix ?? ''}
              onChange={(e) => patch({ proposedFix: e.target.value })}
            />
          </div>

          <div className={styles.field}>
            <label>Trạng thái đề xuất</label>
            <div className={styles.statusToggle}>
              <button
                className={`${styles.statusBtn} ${form.proposalStatus === FallWarningProposalStatus.NotProposed ? styles.statusBtnActive : ''}`}
                onClick={() => patch({ proposalStatus: FallWarningProposalStatus.NotProposed })}
              >
                Chưa đề xuất
              </button>
              <button
                className={`${styles.statusBtn} ${form.proposalStatus === FallWarningProposalStatus.Proposed ? styles.statusBtnActive : ''}`}
                onClick={() => patch({ proposalStatus: FallWarningProposalStatus.Proposed })}
              >
                Đã đề xuất
              </button>
            </div>
          </div>
        </div>

        {/* Section 3: Theo dõi khắc phục */}
        <div className={styles.section} id="fall-section-followup">
          <h2 className={styles.sectionTitle}>
            <i className="fas fa-check-circle" /> Theo Dõi Khắc Phục
          </h2>

          <div className={styles.row}>
            <div className={styles.field}>
              <label>Ngày khảo sát lại</label>
              <input
                type="date"
                value={form.reSurveyDate?.slice(0, 10) ?? ''}
                onChange={(e) => patch({ reSurveyDate: e.target.value || null })}
              />
            </div>
            <div className={styles.field}>
              <label>Trạng thái khắc phục</label>
              <select
                value={form.currentStatus ?? FallWarningCurrentStatus.NotFixed}
                onChange={(e) => patch({ currentStatus: e.target.value as FallWarningCurrentStatus })}
              >
                <option value={FallWarningCurrentStatus.NotFixed}>Chưa khắc phục</option>
                <option value={FallWarningCurrentStatus.InProgress}>Đang khắc phục</option>
                <option value={FallWarningCurrentStatus.Fixed}>Đã khắc phục</option>
              </select>
            </div>
          </div>

          <div className={styles.field}>
            <label>Ghi chú</label>
            <textarea
              rows={2}
              placeholder="Ghi chú thêm..."
              value={form.notes ?? ''}
              onChange={(e) => patch({ notes: e.target.value || null })}
            />
          </div>
        </div>

      </div>
    </div>
  );
};

export default FallLocationWarningFormPage;
